style:
.roomie .rm-eyes-happy,.roomie .rm-eyes-sleep,.roomie .rm-brows,.roomie .rm-drop,.roomie .rm-zzz{display:none}
.roomie.is-happy .rm-eyes-open,.roomie.is-sleepy .rm-eyes-open{display:none}
.roomie.is-happy .rm-eyes-happy{display:inline}
.roomie.is-sleepy .rm-eyes-sleep,.roomie.is-sleepy .rm-zzz{display:inline}
.roomie.is-worried .rm-brows,.roomie.is-worried .rm-drop{display:inline}
.roomie *{transform-box:view-box}
.roomie .rm-bird{transform-origin:64px 118px}
.roomie .rm-eyes-open{transform-origin:64px 60px}
.roomie .rm-tuft{transform-origin:64px 30px}
.roomie .rm-wing-l{transform-origin:29px 76px}
.roomie .rm-wing-r{transform-origin:99px 76px}
.roomie .rm-shadow{transform-origin:64px 122px}
.roomie.is-animated .rm-bird{animation:rm-bob 2.8s ease-in-out infinite}
.roomie.is-animated .rm-shadow{animation:rm-shadow 2.8s ease-in-out infinite}
.roomie.is-animated .rm-eyes-open{animation:rm-blink 4.6s infinite}
.roomie.is-animated .rm-tuft{animation:rm-sway 3.4s ease-in-out infinite}
.roomie.is-animated.is-sleepy .rm-bird{animation:rm-breathe 3.6s ease-in-out infinite}
.roomie.is-animated.is-sleepy .rm-z1{animation:rm-float 2.6s ease-in-out infinite}
.roomie.is-animated.is-sleepy .rm-z2{animation:rm-float 2.6s ease-in-out .9s infinite}
.roomie.is-animated.is-worried .rm-drop{animation:rm-drip 1.6s ease-in infinite}
.roomie.is-animated.is-worried .rm-bird{animation:rm-fidget 1.2s ease-in-out infinite}
.roomie.is-cheer .rm-bird{animation:rm-hop .62s cubic-bezier(.3,.7,.4,1.35) 2}
.roomie.is-cheer .rm-shadow{animation:rm-shadow-hop .62s cubic-bezier(.3,.7,.4,1.35) 2}
.roomie.is-cheer .rm-wing-l{animation:rm-flap-l .16s ease-in-out 8 alternate}
.roomie.is-cheer .rm-wing-r{animation:rm-flap-r .16s ease-in-out 8 alternate}
@keyframes rm-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-2.5px)}}
@keyframes rm-shadow{0%,100%{transform:scaleX(1)}50%{transform:scaleX(.92)}}
@keyframes rm-blink{0%,91%,100%{transform:scaleY(1)}94%{transform:scaleY(.08)}}
@keyframes rm-sway{0%,100%{transform:rotate(-5deg)}50%{transform:rotate(6deg)}}
@keyframes rm-breathe{0%,100%{transform:scale(1,1)}50%{transform:scale(1.025,.975)}}
@keyframes rm-float{0%{transform:translate(0,4px);opacity:0}30%{opacity:1}100%{transform:translate(6px,-10px);opacity:0}}
@keyframes rm-drip{0%{transform:translateY(-3px);opacity:0}25%{opacity:1}100%{transform:translateY(8px);opacity:0}}
@keyframes rm-fidget{0%,100%{transform:rotate(0)}25%{transform:rotate(-2deg)}75%{transform:rotate(2deg)}}
@keyframes rm-hop{0%{transform:translateY(0) scale(1,1)}18%{transform:translateY(2px) scale(1.07,.93)}50%{transform:translateY(-15px) scale(.95,1.06)}82%{transform:translateY(0) scale(1.05,.95)}100%{transform:translateY(0) scale(1,1)}}
@keyframes rm-shadow-hop{0%,100%{transform:scaleX(1);opacity:.22}50%{transform:scaleX(.7);opacity:.12}}
@keyframes rm-flap-l{from{transform:rotate(0)}to{transform:rotate(-34deg)}}
@keyframes rm-flap-r{from{transform:rotate(0)}to{transform:rotate(34deg)}}
.roomie.rm-dino .rm-wing-l{transform-origin:34px 79px}
.roomie.rm-dino .rm-wing-r{transform-origin:94px 79px}
.roomie.rm-dino .rm-tuft{transform-origin:64px 34px}
.roomie.rm-dino .rm-dino-tail{transform-origin:95px 85px}
.roomie.rm-dino.is-animated .rm-tuft{animation:none}
.roomie.rm-dino.is-animated .rm-dino-tail{animation:rm-wag 1.9s ease-in-out infinite}
.roomie.rm-dino.is-cheer .rm-dino-tail{animation:rm-wag .3s ease-in-out 4}
@keyframes rm-wag{0%,100%{transform:rotate(0)}50%{transform:rotate(-9deg)}}
@media (prefers-reduced-motion:reduce){.roomie *{animation:none!important}}
